type MutateBook = <T>(
  bookId: string,
  mutate: (book: ScholarBook) => Promise<T> | T,
) => Promise<{ book: ScholarBook; result: T }>;

type ToolResultFn = (
  action: string,
  summary: string,
  details?: Partial<ToolDetails>,
